#!/usr/bin/env node
// Compiles the skill into portable files for agents other than Claude.
//
//   node build.mjs           write AGENTS.md and adapters/
//   node build.mjs --check   exit 1 if any generated file is stale
//
// Sources: SKILL.md, references/*.md, metadata.json. Never edit the outputs.
// The skill name is read from SKILL.md, so a rename needs no change here.

import { readFileSync, writeFileSync, mkdirSync, existsSync, readdirSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const read = (p) => readFileSync(join(root, p), 'utf8')

const meta = JSON.parse(read('metadata.json'))
const skill = read('SKILL.md')
const front = skill.match(/^---\n([\s\S]*?)\n---\n/)
if (!front) throw new Error('SKILL.md has no frontmatter')
const body = skill.slice(front[0].length).trim()
const name = front[1].match(/^name:\s*(\S+)\s*$/m)?.[1]
const descRaw = front[1].match(/^description:\s*(".*")\s*$/m)?.[1]
if (!name || !descRaw) throw new Error('SKILL.md frontmatter needs name and a double-quoted description')
const description = JSON.parse(descRaw)

// Reference order = the order of the index table in SKILL.md, then any others.
const indexed = [...body.matchAll(/`references\/([a-z0-9\/-]+\.md)`/g)].map((m) => m[1])
const listMd = (dir, base = '') => readdirSync(join(dir, base), { withFileTypes: true }).flatMap((e) => e.isDirectory() ? listMd(dir, `${base}${e.name}/`) : e.name.endsWith('.md') ? [`${base}${e.name}`] : [])
const onDisk = listMd(join(root, 'references')).sort()
const REFERENCES = [...new Set([...indexed, ...onDisk])].filter((f) => onDisk.includes(f))

const demote = (md) => md.replace(/^(#{1,5}) /gm, '#$1 ')
const banner = '<!-- Generated by scripts/build.mjs. Do not edit by hand. -->'

const agents = [
  banner,
  '',
  body.replace(/^# .*$/m, `# ${name}\n\n**Version ${meta.version}** · ${meta.organization} · ${meta.date}\n\n${meta.abstract}`),
  '',
  '---',
  '',
  '# Reference material',
  '',
  "The sections below are the skill's `references/` files, included so this document works alone. Where the text above says \"read `references/x.md`\", read the section of that name below.",
  '',
  ...REFERENCES.map((f) => `<!-- references/${f} -->\n` + demote(read(`references/${f}`).trim()) + '\n'),
].join('\n')

const cursor = [
  '---',
  `description: ${JSON.stringify(description)}`,
  'globs: ["**/pages/work/**", "**/components/work/**", "**/lib/case-*", "**/drafts/*-body-v2.md", "**/skills/' + name + '/**"]',
  'alwaysApply: false',
  '---',
  '',
  banner,
  '',
  body,
  '',
].join('\n')

const chatgpt = [
  banner,
  '',
  '# Instructions for a custom GPT or project',
  '',
  'Paste the block below into the instructions field. Upload `AGENTS.md` from this skill as a knowledge file.',
  '',
  '```',
  'You produce Wugweb pieces in two tracks, using the method in the uploaded file',
  'AGENTS.md: client work (case studies, portfolio, showcase) and Wugweb\'s own',
  'content (blog posts, service pages, site copy), plus their social, deck, Behance',
  'and Dribbble forms. Read AGENTS.md before any such task and follow its modes in',
  'order: Audit, Brief, Media, Look, Body, Layout, SEO and schema, Ship, Forms.',
  '',
  'This list is a short form of the owner\'s standing rules, which AGENTS.md includes in full under references/standing-rules.md. If they differ, that file wins.',
  '',
  'Always:',
  '- Work from one source per piece: the owner\'s body document and media folder,',
  '  or the blog or page record and its brief.',
  '- Show every change as current → proposed with the reason. You propose; the',
  '  owner approves; only then is anything written to the source.',
  '- Back every claim with a screen, a number with source and date, or a named fact.',
  '  Otherwise cut it or mark it "unvalidated".',
  '- Write a caption or alt text only for a screen you have been shown close up.',
  '- Compute every count; if you could not compute it, say so.',
  '- British English, sentence case, headings as claims of 70 characters or fewer.',
  '- For Wugweb\'s own content: no brief, no draft. Ask for the brief.',
  '- Where AGENTS.md lists a matter as open with the owner, use its working',
  '  assumption and mark the output "open".',
  '- Take layout values from the design system documents, never from memory.',
  '- Reply in short, plain English, result first.',
  '',
  'Never:',
  '- Invent numbers, quotes, client names, dates or results.',
  '- Suggest cropping a file, re-encoding, uploading or making media. Showing media',
  '  resized with its aspect ratio kept, and clipping masks, are allowed.',
  '- Post or schedule anything without the owner\'s yes for that exact post.',
  '- Plan content (topics, calendar) or set voice, layout, token or schema rules.',
  '  Say which skill owns it. If a standard is not decided, say so.',
  '- Add HowTo or review-star schema, keyword counts or llms.txt; add FAQPage only from the owner\'s questions and answers when all are visible on the page.',
  '- Use an em or en dash in copy a visitor reads.',
  '',
  'If you can run code, run scripts/case-audit.mjs on the body and',
  'scripts/check-case-page.mjs on the page. If you cannot, apply the same checks by',
  'reading and label the result a manual check. If you cannot open the media,',
  'say which files were not seen and write nothing about them.',
  '```',
  '',
].join('\n')

const openai = [
  '# Generated by scripts/build.mjs. Do not edit by hand.',
  '# Display settings for Codex and the ChatGPT desktop app. Other agents ignore this file.',
  'interface:',
  `  display_name: "${name}"`,
  '  short_description: "Produce every Wugweb piece from the owner\'s source and real evidence"',
  '  default_prompt: "Audit the Wugweb case study I name and propose the body in the v2 grammar as current to proposed."',
  'policy:',
  '  allow_implicit_invocation: true',
  '',
].join('\n')

const exportHeader = `<!-- ${name} ${meta.version}. Built by scripts/build.mjs. Do not edit; edit the source files. -->\n\n`

const outputs = {
  'AGENTS.md': agents,
  [`export/${name}.md`]: exportHeader + agents.replace(banner + '\n\n', ''),
  [`adapters/cursor/${name}.mdc`]: cursor,
  'adapters/chatgpt/instructions.md': chatgpt,
  'agents/openai.yaml': openai,
}

const check = process.argv.includes('--check')
let stale = 0
for (const [path, content] of Object.entries(outputs)) {
  const full = join(root, path)
  const current = existsSync(full) ? readFileSync(full, 'utf8') : null
  if (check) {
    const ok = current === content
    console.log(`${ok ? 'fresh' : 'STALE'}  ${path}`)
    if (!ok) stale++
  } else {
    mkdirSync(dirname(full), { recursive: true })
    writeFileSync(full, content)
    console.log(`wrote  ${path}`)
  }
}
process.exit(stale ? 1 : 0)
